using System.Diagnostics;
using Keynote.Core;
using Keynote.Playback;
namespace Keynote.Tests;
public class PlaybackSafetyTests {
 sealed class BusyInput : IKeyboardInput { public volatile bool Busy=true,Focus=true; public readonly System.Collections.Concurrent.ConcurrentDictionary<string,byte> Held=new(); public bool IsTargetForeground=>Focus; public void Press(string key) { if(Busy && key=="S")throw new KeyboardInputBusyException("Physical key held."); Held[key]=0; } public void Release(string key)=>Held.TryRemove(key,out _); public void ReleaseAll()=>Held.Clear(); public void Dispose()=>ReleaseAll(); }
 [Fact] public async Task PhysicalInputPausesReleasesAndPreservesUnsentChordEvent() { var input=new BusyInput(); using var engine=new PlaybackEngine(input); engine.Start(Song(),Map()); await WaitFor(()=>engine.State==PlaybackState.Paused); Assert.Empty(input.Held); Assert.Equal(0,engine.Diagnostics.Failed); var position=engine.Position; await Task.Delay(50); Assert.Equal(position,engine.Position); Assert.True(engine.AcknowledgeInputPause()); Assert.False(engine.AcknowledgeInputPause()); input.Busy=false; engine.Resume(); await WaitFor(()=>input.Held.ContainsKey("S")); Assert.True(input.Held.ContainsKey("A")); await engine.StopAsync(); Assert.Empty(input.Held); }
 [Fact] public async Task ResumeWhilePhysicalInputStillBusyStaysPausedAndReleasesPartialChord() { var input=new BusyInput{Busy=false}; using var engine=new PlaybackEngine(input); engine.Start(Song(),Map()); await WaitFor(()=>input.Held.Count==2); engine.Pause(); input.Busy=true; engine.Resume(); Assert.Equal(PlaybackState.Paused,engine.State); Assert.Empty(input.Held); Assert.Equal(0,engine.Diagnostics.Failed); await engine.StopAsync(); Assert.False(engine.AcknowledgeInputPause()); }
 [Fact] public async Task FocusLossClearsPendingPhysicalPauseAcknowledgement() { var input=new BusyInput(); using var engine=new PlaybackEngine(input); engine.Start(Song(),Map()); await WaitFor(()=>engine.State==PlaybackState.Paused); input.Focus=false; await Task.Delay(60); Assert.False(engine.AcknowledgeInputPause()); await engine.StopAsync(); }
 static MidiSong Song()=>new("test",new[]{new MidiTrack(0,new[]{new MidiNote(60,100,TimeSpan.Zero,TimeSpan.FromSeconds(1),0),new MidiNote(62,100,TimeSpan.Zero,TimeSpan.FromSeconds(1),0)})});
 static KeyboardMapping Map()=>new(){Keys=new(){{60,"A"},{62,"S"}}};
 static async Task WaitFor(Func<bool> predicate) { var sw=Stopwatch.StartNew(); while(!predicate()) { if(sw.ElapsedMilliseconds>3000)throw new TimeoutException(); await Task.Delay(5); } }
 sealed class RaceInput : IKeyboardInput { public volatile bool Focus=true; public bool FirstRace=true; public readonly System.Collections.Concurrent.ConcurrentDictionary<string,byte> Held=new(); public readonly System.Collections.Concurrent.ConcurrentQueue<string> Events=new(); public bool IsTargetForeground=>Focus;
  public void Press(string key) { if(key=="S" && FirstRace) { FirstRace=false; Focus=false; throw new InvalidOperationException("focus changed during dispatch"); } Held.TryAdd(key,0); Events.Enqueue("+"+key); }
  public void Release(string key) { if(Held.TryRemove(key,out _))Events.Enqueue("-"+key); }
  public void ReleaseAll() { foreach(var k in Held.Keys.ToArray())Release(k); }
  public void Dispose()=>ReleaseAll(); }
 [Fact] public async Task FocusChangeDuringChordPausesAndRetriesUnsentEvent() { var fake=new RaceInput(); using var engine=new PlaybackEngine(fake); engine.Start(Song(),Map()); await WaitFor(()=>engine.State==PlaybackState.Paused); Assert.Empty(fake.Held); fake.Focus=true; engine.Resume(); await WaitFor(()=>fake.Held.ContainsKey("S")); Assert.Equal(PlaybackState.Playing,engine.State); await engine.StopAsync(); Assert.Empty(fake.Held); Assert.Contains("+S",fake.Events); }
 sealed class RetryInput : IKeyboardInput { public bool IsTargetForeground=>true; public volatile bool Held; public volatile bool Fail; public int Calls; public void Press(string key)=>Held=true; public void Release(string key)=>Held=false; public void ReleaseAll() { Calls++; if(Fail) { Fail=false; throw new InvalidOperationException("temporary cleanup failure"); } Held=false; } public void Dispose()=>ReleaseAll(); }
 [Fact] public async Task CleanupFailureIsReportedAndStopRetries() { var input=new RetryInput(); using var engine=new PlaybackEngine(input); var song=new MidiSong("s",new[]{new MidiTrack(0,new[]{new MidiNote(60,100,TimeSpan.Zero,TimeSpan.FromSeconds(2),0)})}); engine.Start(song,Map()); await WaitFor(()=>input.Held); input.Fail=true; engine.Pause(); await WaitFor(()=>engine.State==PlaybackState.Faulted); await engine.StopAsync(); Assert.False(input.Held); Assert.True(engine.Diagnostics.CleanupFailures>=1); Assert.Contains("release",engine.Error!,StringComparison.OrdinalIgnoreCase); }
}
